#!/usr/bin/env python3
import sys
import itertools

def solve(S: str):
    LEN = len(S)
    bit_list = list(itertools.product([0, 1], repeat=LEN-1))
    s = S[::-1]
    answer=0
    for b in bit_list:
        a = 0
        keta =0 
        for i in range(LEN):
            a += int(s[i])*10**keta
            if i == LEN-1:
                break
            keta+=1
            if b[i] == 1:
                keta = 0
        answer += a
            
            
    print(answer)
    return


# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    S = next(tokens)
    solve(S)

if __name__ == '__main__':
    main()
